@startuml

class Ingredient {
  + name : string
  + measuring_unit : string
  + quantity_in_stock : float
}

class Dish {
  + name : string
  + numeric_identifier : int
}

class IngredientDish {
  + quantity : float
}

class Table {
  + numeric_identifier : int
  + maximum_amount_of_people : int
}

class Meal {
  + date : date
  + start_time : time
  + end_time : time
}

class DishMeal {
  + times_served : int
}

class Waiter {
  + numeric_identifier : int
  + name : string
  + address : string
  + phone_number : string
}

class Client {
  + tax_identification_number : string
  + name : string
  + address : string
}

Dish "*" -- "*" Ingredient : composed of
DishDish "1" -- "*" IngredientDish
IngredientDish "*" -- "1" Ingredient

Meal "*" -- "1" Table
Meal "*" -- "1" Waiter : responsible waiter
Meal "1" -- "*" DishMeal
Dish "1" -- "*" DishMeal

Client "0..1" -- "*" Meal

@enduml

